new='''	private response(payload: Record<string, unknown>, failed = false, workflow: WorkflowState = "ready"): Result {
		return { content: [{ type: "text", text: JSON.stringify(payload) }], details: { computer: { failed, workflow } }, isError: failed };
	}

	private async discover(name: string, input: Record<string, unknown>, signal: AbortSignal): Promise<Result> {
		if (input.query !== undefined && (typeof input.query !== "string" || !input.query.trim() || Array.from(input.query).length > 240))
			throw new Error("Discovery query must be a nonblank string of at most 240 characters.");
		const query = typeof input.query === "string" ? input.query.trim() : undefined;
		const include = input.include_windows === true;
		if (input.include_windows !== undefined && typeof input.include_windows !== "boolean") throw new Error("include_windows must be a boolean.");
		if (include && (!query || input.pid !== undefined)) throw new Error("include_windows requires a named app query without pid.");
		const offset = input.offset ?? 0;
		if (typeof offset !== "number" || !Number.isSafeInteger(offset) || offset < 0) throw new Error("Discovery offset must be a nonnegative safe integer.");
		if (input.pid !== undefined && (typeof input.pid !== "number" || !Number.isSafeInteger(input.pid) || input.pid < 1)) throw new Error("Window lookup requires a positive pid.");
		const operation = input.pid === undefined ? "list_apps" : "list_windows";
		const reply = await abortable(this.driver.call(operation, input.pid === undefined ? {} : { pid: input.pid }, signal), signal);
		const data = driverData(reply);
		const discovered = input.pid === undefined ? data.apps : data.windows;
		const rows = Array.isArray(discovered) ? discovered.filter((row) => !query || [record(row).name, record(row).app_name, record(row).title]
			.some((value) => typeof value === "string" && value.toLowerCase().includes(query.toLowerCase()))) : [];
		const identity = (row: unknown) => {
			const item = record(row);
			return { ...select(item, ["pid", "window_id", "name", "app_name", "title", "active", "running", "is_on_screen", "minimized"]),
				bounds: item.bounds ? select(record(item.bounds), ["x", "y", "width", "height"]) : undefined };
		};
		const items = rows.slice(offset, offset + 50).map(identity);
		const remaining = Math.max(0, rows.length - offset - items.length);
		let enrichment: { pid: number; windows?: ReturnType<typeof identity>[]; error?: string; omitted?: number; next_offset?: number }[] | undefined;
		let guidance = remaining ? "Pass next_offset as offset with the same pid and query. Lists refresh per call." : input.pid === undefined
			? "App names filter app identities, not every window title. Use computer_apps({pid}) to find windows for a running app."
			: "Use computer_observe({pid,window_id}) for an exact returned window.";
		if (include && !driverRefused(reply)) {
			const pids = [...new Set(rows.map((row) => record(row).pid).filter((pid): pid is number => typeof pid === "number" && Number.isSafeInteger(pid) && pid > 0))];
			if (pids.length > 5) guidance = "More than five running processes matched. Narrow the query or choose one positive pid with computer_apps({pid}); no windows were selected automatically.";
			else {
				let budget = 50;
				enrichment = [];
				for (const pid of pids) {
					signal.throwIfAborted();
					try {
						const windowsReply = await abortable(this.driver.call("list_windows", { pid }, signal), signal);
						if (driverRefused(windowsReply)) { enrichment.push({ pid, error: nativeReason(windowsReply) }); continue; }
						const windows = driverData(windowsReply).windows;
						if (!Array.isArray(windows)) { enrichment.push({ pid, error: "windows_unavailable" }); continue; }
						const subset = windows.slice(0, budget).map(identity);
						const omitted = windows.length - subset.length;
						enrichment.push({ pid, windows: subset, omitted: omitted || undefined, next_offset: omitted ? subset.length : undefined });
						budget -= subset.length;
					} catch (error) {
						if (signal.aborted || !(error instanceof CaptureError)) throw error;
						enrichment.push({ pid, error: error.code });
					}
				}
				guidance = "Use computer_observe({pid,window_id}) for returned windows. For omitted windows call computer_apps({pid,offset:next_offset}); per-PID lookup failures may be retried by pid.";
			}
		}
		return this.response({ kind: input.pid === undefined ? "apps" : "windows", phase: "native_result", code: driverRefused(reply) ? nativeReason(reply) : undefined,
			...select(data, ["pid", "window_id", "name", "title"]), items, windows_by_pid: enrichment, query, offset, total: rows.length,
			omitted: remaining || undefined, next_offset: remaining ? offset + 50 : undefined, guidance }, driverRefused(reply));
	}

	private async launch(input: Record<string, unknown>, signal: AbortSignal): Promise<Result> {
		if (typeof input.name !== "string" || !input.name.trim() || input.name.length > 500) throw new Error("Launch requires a nonblank app name.");
		const reply = await abortable(this.driver.call("launch_app", { name: input.name }, signal), signal);
		const data = driverData(reply);
		const failed = driverRefused(reply);
		const pid = typeof data.pid === "number" && Number.isSafeInteger(data.pid) && data.pid > 0 ? data.pid : undefined;
		const windowId = typeof data.window_id === "number" && Number.isSafeInteger(data.window_id) && data.window_id > 0 ? data.window_id : undefined;
		const guidance = pid && windowId && !failed ? `Use computer_observe({pid:${pid},window_id:${windowId}}) to capture the exact target before input.`
			: `Launch ${failed ? "may have completed despite an unsuccessful reply" : "returned no exact window"}. Use computer_apps({${pid ? `pid:${pid}` : `query:${JSON.stringify(input.name)}`}}) to discover a window before another launch or input.`;
		return this.response({ kind: "launch", operation: "launch_app", target: { name: input.name }, ...outcome(reply),
			input: "not_applicable", pid, window_id: windowId, guidance }, failed);
	}

	async execute(name: string, input: Record<string, unknown>, signal?: AbortSignal): Promise<Result> {
		const combined = AbortSignal.any([this.abort.signal, this.lease.signal, AbortSignal.timeout(90000), ...(signal ? [signal] : [])]);
		let phase = "validation";
		let dispatched = false;
		let operation = name;
		let target: Target | undefined;
		let actionOutcome: ReturnType<typeof outcome> | undefined;
		try {
			const result = await this.lease.run(async (): Promise<Result> => {
				if (!Object.hasOwn(computerSchemas, name) && name !== "computer_hover") throw new Error("Unknown computer operation.");
				const schema = computerSchemas[name as keyof typeof computerSchemas];
				const properties: Record<string, unknown> = name === "computer_hover" ? { desktop: 1, foreground: 1, observation: 1, x: 1, y: 1 } : schema.properties;
				if (Object.keys(input).some((key) => !Object.hasOwn(properties, key))) throw new Error("Unsupported computer argument. Use image coordinates only.");
				const previous = this.observation;
				if (name === "computer_apps") return this.discover(name, input, combined);
				this.observation = undefined;
				if (name === "computer_launch") {
					operation = "launch_app";
					phase = "native_request";
					dispatched = true;
					return this.launch(input, combined);
				}
				target = targetFrom(input);
				if (name === "computer_observe") {
					const crop = input.crop === undefined ? undefined : this.crop(input, this.fresh(input, previous));
					phase = "post_action_capture";
					const captured = await this.capture(target, combined, previous, crop);
					const unchanged = this.lastCapture?.fingerprint === captured.fingerprint && sameTarget(this.lastCapture.target, target);
					const repeats = crop ? 0 : unchanged ? (this.lastCapture?.repeats ?? 0) + 1 : 1;
					this.lastCapture = { fingerprint: captured.fingerprint, target, repeats };
					if (repeats >= 3) return this.response({ code: "unchanged_polling_limit", observation: "unavailable", guidance: "Three full captures are unchanged. Stop polling and reconsider the target or approach." }, true, "stopped");
					return this.imageResult(captured, { kind: "observation", unchanged });
				}
				const grounded = this.fresh(input, previous);
				const action = this.action(name, input, grounded);
				operation = action.operation;
				const args = action.args;
				const { button = "left", count = 1, modifier = [], ...clickArgs } = args;
				const signature = JSON.stringify({ operation, args: operation === "click"
					? { ...clickArgs, button, count, modifier: Array.isArray(modifier) ? [...new Set(modifier)].sort() : modifier } : args });
				if (this.lastAction?.unchanged && this.lastAction.signature === signature && this.lastAction.fingerprint === grounded.fingerprint)
					throw new Error("The identical action had no visible change. Choose a different grounded action; never retry blindly.");
				combined.throwIfAborted();
				phase = "native_request";
				dispatched = true;
				const reply = await abortable(this.driver.call(operation, args, combined), combined);
				combined.throwIfAborted();
				actionOutcome = outcome(reply, name === "computer_text" ? input.text : undefined);
				const failed = driverRefused(reply) || driverData(reply).effect === "partial" || driverData(reply).status === "partial";
				const backgroundUnavailable = actionOutcome.code === "background_unavailable";
				const recoveryGuidance = actionOutcome.retry_from_character !== undefined
					? "Verify the field in a fresh image before considering any remaining suffix. retry_from_character is a zero-based Unicode code-point offset, not UTF-16. retryable is driver advice, not authorization to retry." : undefined;
				if (name === "computer_hover") await abortable(new Promise<void>((resolve) => setTimeout(resolve, 700)), combined);
				phase = "post_action_capture";
				try {
					const after = await this.capture(target, combined);
					const unchanged = after.fingerprint === grounded.fingerprint;
					this.lastAction = { signature, fingerprint: after.fingerprint, unchanged };
					this.lastCapture = { fingerprint: after.fingerprint, target, repeats: 0 };
					return this.imageResult(after, { kind: "action", operation, target, ...actionOutcome, failed, unchanged,
						guidance: ["Inspect the post-action image before any next action. An unchanged image does not prove failure; never repeat input blindly.",
							backgroundUnavailable ? "After this fresh capture, foreground input may be considered if permitted, not another background shortcut." : undefined,
							recoveryGuidance].filter(Boolean).join(" ") });
				} catch (error) {
					combined.throwIfAborted();
					if (!(error instanceof CaptureError)) throw error;
					this.lastAction = { signature, fingerprint: grounded.fingerprint, unchanged: true };
					return this.response({ kind: "action", operation, target, ...actionOutcome, phase: "post_action_capture", capture_error: error.code,
						observation: "unavailable", guidance: `${name === "computer_hover" ? "Pointer movement" : "Input"} may have taken effect. ${error.code === "target_not_found" || error.code === "window_target_mismatch" ? "Find the target with computer_apps({pid}) or observe the desktop." : "Get a fresh capture of the exact target"} before another action; never repeat blindly. ${recoveryGuidance ?? ""}` }, true);
				}
			}, combined);
			if (result.details.computer.workflow !== "ready") return this.finish(result);
			return result;
		} catch (error) {
			const fatal = combined.aborted || this.abort.signal.aborted || this.lease.signal.aborted || error instanceof DriverCallError || !(error instanceof ObservationError || error instanceof CaptureError || phase === "validation");
			if (error instanceof DriverCallError) { phase = error.phase; dispatched = error.dispatched; }
			const code = error instanceof ObservationError || error instanceof CaptureError ? error.code : error instanceof DriverCallError
				? error.dispatched ? "input_dispatch_failed" : "adapter_preflight_failed" : fatal ? "workflow_unavailable" : "invalid_arguments";
			const response = this.response({ kind: name === "computer_apps" ? "apps" : name === "computer_launch" ? "launch" : "action", operation, target,
				...actionOutcome, phase, code, input: dispatched ? "uncertain" : "not_dispatched", applicationEffect: "unverified",
				observation: "unavailable", message: dispatched ? "Request began; effects may have occurred." : "No input was sent by this call.",
				guidance: dispatched ? name === "computer_launch" ? `Use computer_apps({query:${JSON.stringify(input.name)}) before considering another launch.`
					: "Capture the exact target again and inspect possible effects before further input. Never repeat blindly." : freshActionGuidance }, true, fatal ? "stopped" : "ready");
			return fatal ? this.finish(response) : response;
		}
	}

	private async finish(result: Result): Promise<Result> {
		try { await this.close(); return { ...result, details: { ...result.details, computer: { failed: result.details.computer.failed, workflow: "stopped" } } }; }
		catch { return { ...result, details: { ...result.details, computer: { failed: true, workflow: "cleanup_unconfirmed" } }, isError: true,
			content: [...result.content, { type: "text", text: JSON.stringify({ phase: "cleanup", cleanup: "unconfirmed", guidance: "Desktop ownership retained. Do not start another workflow until shutdown is confirmed." }) }] }; }
	}
